artifacts.source_unit_schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/krapcys1-maker/adaptive-agent-memory-research/data/lab/pmlab-natural-history-v0/source-unit-contract-v0.schema.json",
  "title": "PMLAB natural-history source unit v0",
  "type": "object",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {"properties": {"git_object_format": {"const": "sha1"}}, "required": ["git_object_format"]},
      "then": {"properties": {"snapshot_commit": {"pattern": "^[a-f0-9]{40}$"}}}
    },
    {
      "if": {"properties": {"git_object_format": {"const": "sha256"}}, "required": ["git_object_format"]},
      "then": {"properties": {"snapshot_commit": {"pattern": "^[a-f0-9]{64}$"}}}
    }
  ],
  "required": [
    "contract_version",
    "unit_id",
    "snapshot_commit",
    "git_object_format",
    "source_type",
    "path",
    "locator",
    "search_text",
    "search_text_sha256",
    "source_blob_sha256",
    "source_git_object",
    "eligibility_class",
    "backend_visible_fields"
  ],
  "properties": {
    "contract_version": {
      "const": "0.2.0"
    },
    "unit_id": {
      "type": "string",
      "pattern": "^U-[a-f0-9]{16}$",
      "description": "Opaque ID derived from contract version, source type, path, locator, and search-text hash. Snapshot commit is excluded so an unchanged unit keeps its ID across historical snapshots. It must not encode time, category, or relevance."
    },
    "snapshot_commit": {
      "type": "string",
      "pattern": "^(?:[a-f0-9]{40}|[a-f0-9]{64})$"
    },
    "git_object_format": {
      "enum": ["sha1", "sha256"]
    },
    "source_type": {
      "enum": [
        "project_memory_event",
        "markdown_section",
        "catalog_row",
        "lab_summary_section"
      ]
    },
    "path": {
      "type": "string",
      "minLength": 1
    },
    "locator": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "value"],
      "properties": {
        "kind": {
          "enum": ["event_id", "heading_path_and_occurrence", "row_primary_key"]
        },
        "value": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "search_text": {
      "type": "string",
      "minLength": 1,
      "description": "The byte-identical UTF-8 text passed to every retrieval representation before its documented tokenizer."
    },
    "search_text_sha256": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    },
    "source_blob_sha256": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$",
      "description": "Portable SHA-256 of the exact historical file bytes, distinct from Git's typed object name."
    },
    "source_git_object": {
      "type": "object",
      "additionalProperties": false,
      "allOf": [
        {
          "if": {"properties": {"algorithm": {"const": "sha1"}}, "required": ["algorithm"]},
          "then": {"properties": {"object_id": {"pattern": "^[a-f0-9]{40}$"}}}
        },
        {
          "if": {"properties": {"algorithm": {"const": "sha256"}}, "required": ["algorithm"]},
          "then": {"properties": {"object_id": {"pattern": "^[a-f0-9]{64}$"}}}
        }
      ],
      "required": ["algorithm", "object_id"],
      "properties": {
        "algorithm": {"enum": ["sha1", "sha256"]},
        "object_id": {"type": "string", "pattern": "^(?:[a-f0-9]{40}|[a-f0-9]{64})$"}
      }
    },
    "eligibility_class": {
      "enum": [
        "canonical_research",
        "canonical_memory",
        "reviewed_lab_summary",
        "reviewed_catalog"
      ]
    },
    "valid_time": {
      "type": ["string", "null"],
      "format": "date-time"
    },
    "recorded_time": {
      "type": ["string", "null"],
      "format": "date-time"
    },
    "status": {
      "type": ["string", "null"]
    },
    "trust": {
      "type": ["string", "null"]
    },
    "source_aliases": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["path", "locator"],
        "properties": {
          "path": {"type": "string"},
          "locator": {"type": "string"}
        }
      },
      "description": "Exact duplicate byte sources collapsed before ranking; near duplicates are not collapsed."
    },
    "backend_visible_fields": {
      "const": ["unit_id", "search_text"],
      "description": "The primary B1/B2/C1/C2 comparison receives no path, filename, time, status, trust, or label."
    }
  }
}

artifacts.query_log_schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/krapcys1-maker/adaptive-agent-memory-research/data/lab/pmlab-natural-history-v0/query-log-contract-v0.schema.json",
  "title": "PMLAB authentic pre-output query log v0",
  "type": "object",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {"properties": {"git_object_format": {"const": "sha1"}}, "required": ["git_object_format"]},
      "then": {"properties": {"query_cutoff_commit": {"pattern": "^[a-f0-9]{40}$"}}}
    },
    {
      "if": {"properties": {"git_object_format": {"const": "sha256"}}, "required": ["git_object_format"]},
      "then": {"properties": {"query_cutoff_commit": {"pattern": "^[a-f0-9]{64}$"}}}
    }
  ],
  "required": [
    "query_id",
    "recorded_at",
    "query_text",
    "language",
    "origin_type",
    "origin_receipt",
    "query_cutoff_commit",
    "git_object_format",
    "pre_output_attestation",
    "collection_phase",
    "recorded_by_role",
    "storage_class"
  ],
  "properties": {
    "query_id": {
      "type": "string",
      "pattern": "^Q-[a-f0-9]{16}$"
    },
    "recorded_at": {
      "type": "string",
      "format": "date-time"
    },
    "query_text": {
      "type": "string",
      "minLength": 3
    },
    "language": {
      "enum": ["pl", "en", "mixed", "other"]
    },
    "origin_type": {
      "enum": [
        "verbatim_user_question",
        "pre-investigation_issue",
        "pre-answer_debug_question",
        "pre-evidence_reviewer_question",
        "authored_diagnostic_development_only"
      ]
    },
    "origin_receipt": {
      "type": "object",
      "additionalProperties": false,
      "required": ["mode", "value"],
      "properties": {
        "mode": {"enum": ["public_git_locator", "private_random_receipt", "private_keyed_digest"]},
        "value": {"type": "string", "minLength": 3}
      },
      "description": "Public locators may be explicit. Private origins use an independently random receipt or keyed digest whose mapping/key remains outside Git; an unkeyed content or locator hash is forbidden."
    },
    "query_cutoff_commit": {
      "type": "string",
      "pattern": "^(?:[a-f0-9]{40}|[a-f0-9]{64})$"
    },
    "git_object_format": {
      "enum": ["sha1", "sha256"]
    },
    "pre_output_attestation": {
      "const": "No candidate backend output or gold evidence search was viewed before this query was frozen."
    },
    "collection_phase": {
      "enum": ["retrospective_development", "prospective_test"]
    },
    "recorded_by_role": {
      "enum": ["user", "research_agent", "human_reviewer", "automated_capture"]
    },
    "storage_class": {
      "enum": ["git_public", "local_restricted"],
      "description": "Local-restricted query text and origin mappings must not be committed to the public repository; public artifacts expose opaque IDs and aggregate receipts only."
    },
    "exclusion_reason": {
      "type": ["string", "null"]
    }
  }
}
